inline constexpr int N = 48;

inline const Portrait *find(const char *driver_id) {
  if (driver_id == nullptr || !*driver_id) return nullptr;
  for (int i = 0; i < N; i++)
    if (std::strcmp(driver_id, P[i].driver_id) == 0) return &P[i];
  return nullptr;   // no portrait: render a text-only card (RACE-13e)
}

